    expectTypeOf<SetContext>(ctx);

    return next({ ctx });
  });

  protectedProcedure.use(async ({ next, ctx }) => {
    // Should be definitely defined
    ctx.user.id;
    ctx.session.id;

    expectTypeOf<SetContext>(ctx);

    return next({
      ctx: {
        ...ctx,
      },
    });
  });
});
